add_action( 'woocommerce_cart_calculate_fees', 'perfectpixel_surcharge_by_state' );

function perfectpixel_surcharge_by_state( $cart ) {
	if ( ( is_admin() && ! wp_doing_ajax() ) || ! $cart->needs_shipping() ) {
		return;
	}
	$customer = WC()->customer;
	$states   = array_filter( array_map( 'trim', explode( ',', strtoupper( '{{surcharge_states}}' ) ) ) );
	if ( ! $customer || strtoupper( '{{surcharge_country}}' ) !== $customer->get_shipping_country() || ! in_array( strtoupper( $customer->get_shipping_state() ), $states, true ) ) {
		return;
	}
	$cart->add_fee( '{{surcharge_label}}', (float) '{{surcharge_amount}}', 'yes' === '{{surcharge_taxable}}' );
}
